            {
                var parameterValue = Convert.ToString(value);

                var path = FindPath(parameterValue);
                if (path == null)
                {
                    return false;
                }

                var archiveData = FindArchiveData(parameterValue);
                if (archiveData == null)
                {
                    return false;
                }

                try
                {
                    // is this a valid date ?
                    archiveData.ToDateTime();
                }
