            {
                using (@lock)
                {
                    IEnumerable<QueuedJobRecord> messages;
                    var currentBatch = 0;
                    while (batchCount > currentBatch && (messages = _jobsQueueManager.Value.GetJobs(0, batchSize).ToArray()).Any())
                    {
                        foreach (var message in messages)
                        {
                            ProcessMessage(message);
                        }

                        currentBatch++;
                    }
                }
            }

